mapper.select:
select u.user_id, u.name userName, u.source_user_id userSourceId, u.flag userFlag, o.org_id, o.org_name, o.source_org_id orgSourceId, rel.rel_id, rel.rel_cd from u_user u left join u_org_staff_rel rel on rel.staff_id = u.user_id left join u_org o on o.org_id = rel.org_id where u.status_cd = '0' and o.status_cd = '0' and rel.status_cd = '0'
and o.source_org_id = #{sourceOrgId}
and u.user_id = #{userId}
